<?php
/** @noinspection PhpUnhandledExceptionInspection */
declare(strict_types=1);

// Test generated by Claude Code (with manual adjustments).

namespace Tests\Offer\Action\Query;

use Module\Offer\Action\Query\AdminGetOfferDetailsQry;
use Module\Offer\Model\Offer;
use Module\Offer\Model\OfferRepository;
use Module\Product\Action\Dto\ProductDetailsDto;
use Module\Product\Action\Query\GetProductDetailsQry;
use Module\Shared\Exception\AppValidationException;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\Attributes\Test;
use Tests\IntegrationTestCase;

class AdminGetOfferDetailsQryTest extends IntegrationTestCase
{
    private AdminGetOfferDetailsQry $sut;

    private OfferRepository $offerRepository;

    private const int STORE_ID = 1;

    public function setUp(): void
    {
        parent::setUp();

        $this->offerRepository = $this->container->get(OfferRepository::class);

        $getProductDetailsQry = $this->createStub(GetProductDetailsQry::class);
        $getProductDetailsQry->method('handle')->willReturnMap([
            [100, self::STORE_ID, new ProductDetailsDto(id: 100, ean: '5901234123457', name: 'Product Name', imageUrl: 'https://img.example.com/p.jpg', quantity: 7000)],
            [101, self::STORE_ID, new ProductDetailsDto(id: 101, ean: '5901234123111', name: 'Product Name 101', imageUrl: null, quantity: null)],
        ]);

        $this->sut = new AdminGetOfferDetailsQry(
            $this->offerRepository,
            $getProductDetailsQry
        );

        $this->prepareDb();
    }

    /**
     * @param class-string $expectedExceptionClass
     */
    #[Test, DataProvider('dataProviderHandle')]
    public function handle(
        int $offerId,
        string $expectedExceptionClass,
        string $expectedExceptionMessage,
        ?string $expectedProductName,
        ?string $expectedImageUrl,
        ?int $expectedQuantity,
        ?bool $expectedVisible,
    ): void {
        if ($expectedExceptionClass) {
            $this->expectException($expectedExceptionClass);
            $this->expectExceptionMessageMatches('/^' . preg_quote($expectedExceptionMessage, '/') . '$/');
        }

        $result = $this->sut->handle($offerId);

        $this->assertSame($offerId, $result->id);
        $this->assertSame($expectedProductName, $result->productName);
        $this->assertSame($expectedImageUrl, $result->imageUrl);
        $this->assertSame($expectedQuantity, $result->quantity);
        $this->assertSame($expectedVisible, $result->visible);
    }

    /**
     * @return array<string, array<string, mixed>>
     */
    public static function dataProviderHandle(): array
    {
        return [
            'offer not found' => [
                'offerId' => 9999,
                'expectedExceptionClass' => AppValidationException::class,
                'expectedExceptionMessage' => 'offerId: Offer not found',
                'expectedProductName' => null,
                'expectedImageUrl' => null,
                'expectedQuantity' => null,
                'expectedVisible' => null,
            ],
            'success - uses offer productName' => [
                'offerId' => 710,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => 'Offer Product Name',
                'expectedImageUrl' => 'https://img.example.com/p.jpg',
                'expectedQuantity' => 7000,
                'expectedVisible' => true,
            ],
            'success - falls back to product name when offer name is null' => [
                'offerId' => 711,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => 'Product Name 101',
                'expectedImageUrl' => '',
                'expectedQuantity' => null,
                'expectedVisible' => false,
            ],
            'success - no productId yields empty strings and null quantity' => [
                'offerId' => 712,
                'expectedExceptionClass' => '',
                'expectedExceptionMessage' => '',
                'expectedProductName' => '',
                'expectedImageUrl' => '',
                'expectedQuantity' => null,
                'expectedVisible' => true,
            ],
        ];
    }

    private function prepareDb(): void
    {
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-710', productEan: '5901234123457',
            productName: 'Offer Product Name', price: 1000, lowestPrice: 900, visible: true, productId: 100, id: 710));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-711', productEan: '5901234123458',
            productName: null, price: 800, lowestPrice: null, visible: false, productId: 101, id: 711));
        $this->offerRepository->saveWithId(Offer::factory(storeId: self::STORE_ID, externalId: 'EXT-712', productEan: '5901234123459',
            productName: null, price: 500, lowestPrice: null, visible: true, productId: null, id: 712));
        $this->offerRepository->flush();
    }
}
